import json,re,sys
from pathlib import Path
source,report,out=map(Path,sys.argv[1:])
screen=json.loads(report.read_text())
ids={entry['id'] for entry in screen['candidate_pointers']}
rows=[]
for rel in json.loads(source.read_text())['releases']:
    if rel['id'] not in ids: continue
    tender=rel['tender']
    contexts=[]
    def visit(value,path):
        if isinstance(value,dict):
            for key,child in value.items(): visit(child,path+[key])
        elif isinstance(value,list):
            for i,child in enumerate(value): visit(child,path+[i])
        elif isinstance(value,str) and path[-1] in ('title','description','name'):
            for m in re.finditer('Data Quality',value,re.I):
                contexts.append({'field':path,'quote':value[max(0,m.start()-100):m.end()+360]})
    visit(tender,[])
    rows.append({'id':rel['id'],'ocid':rel['ocid'],'tag':rel.get('tag'),'title':tender['title'],'lots':[lot.get('title') for lot in tender['lots']],'contexts':contexts})
out.write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n')
print(out.read_text())
